1	package agentusage
2	
3	import (
4		"cmp"
5		"slices"
6	)
7	
8	// pos orders lines the way ParseSession reads them (D3).
9	type pos struct {
10		rank string // "0" parent; "1"+agentID+"\x00"+baseName for a sub-agent
11		off  int64
12	}
13	
14	// parentRank is the rank of the parent transcript; it sorts before every
15	// sub-agent rank.
16	const parentRank = "0"
17	
18	// subAgentRank is the rank of a sub-agent's transcript: sub-agents are read by
19	// ID, then by base name.
20	func subAgentRank(agentID, name string) string { return "1" + agentID + "\x00" + name }
21	
22	// transcriptRank is subAgentRank made unique per transcript: the raw ID and
23	// the path break ties between sub-agents whose sanitized IDs and base names
24	// coincide. It is a function of the transcript alone, so it is stable from one
25	// pass to the next, and it doubles as the agent's key in a table.
26	func transcriptRank(agentID, name, rawID, path string) string {
27		return subAgentRank(agentID, name) + "\x00" + rawID + "\x00" + path
28	}
29	
30	// compare orders positions by rank, then by offset.
31	func (p pos) compare(o pos) int {
32		if c := cmp.Compare(p.rank, o.rank); c != 0 {
33			return c
34		}
35		return cmp.Compare(p.off, o.off)
36	}
37	
38	// msgKey identifies one message of a session. A message with an id is keyed
39	// by the id alone; one without is keyed by where it was read (file rank and
40	// offset).
41	type msgKey struct {
42		id   string
43		file string
44		off  int64
45	}
46	
47	// entry is the last state seen of one message. Which line is "last" is a
48	// function of positions, never of arrival.
49	type entry struct {
50		first, last pos
51		agent       string // agent ID of the last line; "" for the parent
52		file        string // base name of one file the message was seen in
53		otherFiles  []string
54		model       string
55		tokens      Tokens
56		stopNull    bool
57	}
58	
59	// addFile remembers that the message was also seen in the file named name.
60	func (e *entry) addFile(name string) {
61		if e.file == name || slices.Contains(e.otherFiles, name) {
62			return
63		}
64		e.otherFiles = append(e.otherFiles, name)
65	}
66	
67	// absorb folds o into e: the greatest position gives the state, the smallest
68	// gives first, and the files are united.
69	func (e *entry) absorb(o *entry) {
70		if o.last.compare(e.last) >= 0 {
71			e.last, e.agent, e.model, e.tokens, e.stopNull = o.last, o.agent, o.model, o.tokens, o.stopNull
72		}
73		if o.first.compare(e.first) < 0 {
74			e.first = o.first
75		}
76		e.addFile(o.file)
77		for _, f := range o.otherFiles {
78			e.addFile(f)
79		}
80	}
81	
82	// spill totals the lines that no longer get a table entry.
83	type spill struct {
84		tokens   Tokens
85		messages int
86		partial  int
87		models   modelSet
88	}
89	
90	// issueAt is a FileIssue with the position of the line it describes.
91	type issueAt struct {
92		p  pos
93		fi FileIssue
94	}
95	
96	// compare orders issues by position, then kind, then file.
97	func (a issueAt) compare(b issueAt) int {
98		if c := a.p.compare(b.p); c != 0 {
99			return c
100		}
101		if c := cmp.Compare(a.fi.Kind, b.fi.Kind); c != 0 {
102			return c
103		}
104		return cmp.Compare(a.fi.File, b.fi.File)
105	}
106	
107	// table folds lines into per-key last states, ordered by position (D3). It
108	// is both the content of a Delta and the state of an Aggregate. Two declared
109	// exceptions to order-freedom: which no-id lines spill past maxNoIDEntries
110	// (the smallest positions of each merge are kept, see mergeCapped), and which
111	// models fill a spill's maxModelsPerAgent (arrival order).
112	type table struct {
113		entries map[msgKey]*entry
114		noID    int // entries holding a line without message id
115		spill   map[string]*spill
116		// counters of lines; CrossFileDuplicates is derived by finish.
117		unreadable, noUsage, noMessageID, oversized int
118		// capped holds the unreadable/oversized issues per file name, trimmed to
119		// the maxFileIssuesPerFile smallest positions; stateIssues holds the
120		// other kinds, which occur once per file.
121		capped      map[string][]issueAt
122		stateIssues []issueAt
123		// versions maps a distinct client version to its first position, at most
124		// maxVersions of them (the smallest positions).
125		versions map[string]pos
126	}
127	
128	func newTable() *table {
129		return &table{
130			entries:  map[msgKey]*entry{},
131			spill:    map[string]*spill{},
132			capped:   map[string][]issueAt{},
133			versions: map[string]pos{},
134		}
135	}
136	
137	// addLine decodes one line of the file named name for agent ("" for the
138	// parent) and folds it. Synthetic and ignored lines never count.
139	func (t *table) addLine(agent, name string, p pos, line []byte) {
140		r, kind := decodeLine(line)
141		if kind != kindUnreadable {
142			t.noteVersion(r.Version, p)
143		}
144		switch kind {
145		case kindUsage:
146			t.addUsage(agent, name, p, r)
147		case kindNoUsage:
148			t.noUsage++
149		case kindUnreadable:
150			t.unreadable++
151			t.addFileIssue(name, p, IssueUnreadable)
152		case kindIgnored, kindSynthetic:
153		}
154	}
155	
156	// addOversized counts a line longer than MaxLineBytes that started at p.
157	func (t *table) addOversized(name string, p pos) {
158		t.oversized++
159		t.addFileIssue(name, p, IssueOversized)
160	}
161	
162	// addUsage folds one usage record in.
163	func (t *table) addUsage(agent, name string, p pos, r record) {
164		key := msgKey{id: r.MessageID}
165		if r.MessageID == "" {
166			key = msgKey{file: p.rank, off: p.off}
167			t.noMessageID++
168			if _, ok := t.entries[key]; !ok {
169				if t.noID >= maxNoIDEntries {
170					t.addSpill(agent, r)
171					return
172				}
173				t.noID++
174			}
175		}
176		t.put(key, &entry{
177			first: p, last: p, agent: agent, file: name,
178			model: r.Model, tokens: r.Usage, stopNull: r.StopNull,
179		})
180	}
181	
182	// put folds e into the table under key; the table keeps its own copy.
183	func (t *table) put(key msgKey, e *entry) {
184		if cur, ok := t.entries[key]; ok {
185			cur.absorb(e)
186			return
187		}
188		c := *e
189		c.otherFiles = slices.Clone(e.otherFiles)
190		t.entries[key] = &c
191	}
192	
193	// addSpill counts a no-id line that gets no table entry.
194	func (t *table) addSpill(agent string, r record) {
195		sp := t.spill[agent]
196		if sp == nil {
197			sp = &spill{}
198			t.spill[agent] = sp
199		}
200		sp.absorbRecord(r)
201	}
202	
203	// spillEntry totals an entry that gets no slot in the table.
204	func (t *table) spillEntry(e *entry) {
205		sp := t.spill[e.agent]
206		if sp == nil {
207			sp = &spill{}
208			t.spill[e.agent] = sp
209		}
210		sp.tokens = sp.tokens.Add(e.tokens)
211		sp.messages++
212		if e.stopNull {
213			sp.partial++
214		}
215		sp.models.add(e.model)
216	}
217	
218	func (s *spill) absorbRecord(r record) {
219		s.tokens = s.tokens.Add(r.Usage)
220		s.messages++
221		if r.StopNull {
222			s.partial++
223		}
224		s.models.add(r.Model)
225	}
226	
227	// noteVersion records a client version with its first position, keeping the
228	// maxVersions smallest.
229	func (t *table) noteVersion(v string, p pos) {
230		v = sanitizeLabel(v)
231		if v == "" {
232			return
233		}
234		if cur, ok := t.versions[v]; ok {
235			if p.compare(cur) < 0 {
236				t.versions[v] = p
237			}
238			return
239		}
240		if len(t.versions) >= maxVersions {
241			worst, wp := "", pos{}
242			for k, kp := range t.versions {
243				if worst == "" || kp.compare(wp) > 0 {
244					worst, wp = k, kp
245				}
246			}
247			if p.compare(wp) >= 0 {
248				return
249			}
250			delete(t.versions, worst)
251		}
252		t.versions[v] = p
253	}
254	
255	// addFileIssue records an issue of the file named name. Unreadable and
256	// oversized ones are kept at most maxFileIssuesPerFile per file (the counters
257	// are not capped); the other kinds occur once per file and are always kept.
258	func (t *table) addFileIssue(name string, p pos, kind IssueKind) {
259		it := issueAt{p: p, fi: FileIssue{File: name, Offset: p.off, Kind: kind}}
260		if kind != IssueUnreadable && kind != IssueOversized {
261			t.stateIssues = append(t.stateIssues, it)
262			return
263		}
264		t.capped[name] = trimIssues(append(t.capped[name], it), 2*maxFileIssuesPerFile)
265	}
266	
267	// trimIssues keeps the maxFileIssuesPerFile smallest issues once s has grown
268	// to limit entries.
269	func trimIssues(s []issueAt, limit int) []issueAt {
270		if len(s) < limit {
271			return s
272		}
273		slices.SortFunc(s, issueAt.compare)
274		return s[:min(len(s), maxFileIssuesPerFile)]
275	}
276	
277	// merge folds o into t as if o's lines had been added to t. o is not modified
278	// and shares nothing with t afterwards.
279	func (t *table) merge(o *table) { t.mergeSkipping(o, nil) }
280	
281	// mergeCapped is merge with the per-session bound on lines without id: the
282	// ones o adds past maxNoIDEntries are spilled instead of getting an entry,
283	// the earliest positions being kept. Which lines spill therefore follows
284	// position, not arrival, but the totals do not depend on it.
285	func (t *table) mergeCapped(o *table) {
286		var fresh []msgKey
287		for k := range o.entries {
288			if _, had := t.entries[k]; k.id == "" && !had {
289				fresh = append(fresh, k)
290			}
291		}
292		room := max(maxNoIDEntries-t.noID, 0)
293		if len(fresh) <= room {
294			t.merge(o)
295			return
296		}
297		slices.SortFunc(fresh, func(a, b msgKey) int { return o.entries[a].first.compare(o.entries[b].first) })
298		skip := make(map[msgKey]bool, len(fresh)-room)
299		for _, k := range fresh[room:] {
300			skip[k] = true
301		}
302		t.mergeSkipping(o, skip)
303	}
304	
305	// mergeSkipping is merge, except that the entries named by skip are spilled.
306	func (t *table) mergeSkipping(o *table, skip map[msgKey]bool) {
307		for k, e := range o.entries {
308			if skip[k] {
309				t.spillEntry(e)
310				continue
311			}
312			_, had := t.entries[k]
313			t.put(k, e)
314			if !had && k.id == "" {
315				t.noID++
316			}
317		}
318		for agent, sp := range o.spill {
319			dst := t.spill[agent]
320			if dst == nil {
321				dst = &spill{}
322				t.spill[agent] = dst
323			}
324			dst.tokens = dst.tokens.Add(sp.tokens)
325			dst.messages += sp.messages
326			dst.partial += sp.partial
327			for _, m := range sp.models.list {
328				dst.models.add(m)
329			}
330		}
331		t.unreadable += o.unreadable
332		t.noUsage += o.noUsage
333		t.noMessageID += o.noMessageID
334		t.oversized += o.oversized
335		for name, s := range o.capped {
336			t.capped[name] = trimIssues(append(t.capped[name], s...), 2*maxFileIssuesPerFile)
337		}
338		t.stateIssues = append(t.stateIssues, o.stateIssues...)
339		for v, p := range o.versions {
340			t.noteVersion(v, p)
341		}
342	}
343	
344	// orderedKeys returns the entry keys by first position: the order messages
345	// first appear in a sequential read.
346	func (t *table) orderedKeys() []msgKey {
347		keys := make([]msgKey, 0, len(t.entries))
348		for k := range t.entries {
349			keys = append(keys, k)
350		}
351		slices.SortFunc(keys, func(a, b msgKey) int {
352			if c := t.entries[a].first.compare(t.entries[b].first); c != 0 {
353				return c
354			}
355			return cmp.Or(cmp.Compare(a.id, b.id), cmp.Compare(a.file, b.file), cmp.Compare(a.off, b.off))
356		})
357		return keys
358	}
359	
360	// finish computes the counters of the agents given (identity fields set, the
361	// parent flagged Main), the line diagnostics and the versions, all deep
362	// copies. Agents are matched by key (ID when unset); the Main agent matches
363	// the parent's "".
364	func (t *table) finish(agents []Agent) ([]Agent, Diagnostics, []string) {
365		return t.finishWith(agents, nil)
366	}
367	
368	// finishWith is finish with extra file issues, kept in position order among
369	// the table's own: a session reader passes the states of its cursors.
370	func (t *table) finishWith(agents []Agent, extra []issueAt) ([]Agent, Diagnostics, []string) {
371		out := slices.Clone(agents)
372		idx := make(map[string]int, len(out))
373		for i := range out {
374			out[i].Tokens, out[i].Models = Tokens{}, nil
375			out[i].Messages, out[i].PartialMessages = 0, 0
376			id := cmp.Or(out[i].key, out[i].ID)
377			if out[i].Main {
378				id = ""
379			}
380			out[i].key = ""
381			idx[id] = i
382		}
383		models := make([]modelSet, len(out))
384		cross := 0
385		for _, k := range t.orderedKeys() {
386			e := t.entries[k]
387			cross += len(e.otherFiles)
388			if i, ok := idx[e.agent]; ok {
389				addEntry(&out[i], &models[i], e)
390			}
391		}
392		for agent, sp := range t.spill {
393			if i, ok := idx[agent]; ok {
394				addSpill(&out[i], &models[i], sp)
395			}
396		}
397		for i := range out {
398			out[i].Models = models[i].list
399		}
400		return out, t.diagnostics(cross, extra), t.orderedVersions()
401	}
402	
403	// addEntry adds one message's final state to its agent.
404	func addEntry(ag *Agent, ms *modelSet, e *entry) {
405		ag.Tokens = ag.Tokens.Add(e.tokens)
406		ag.Messages++
407		if e.stopNull {
408			ag.PartialMessages++
409		}
410		ms.add(e.model)
411	}
412	
413	// addSpill adds a spill's totals to its agent.
414	func addSpill(ag *Agent, ms *modelSet, sp *spill) {
415		ag.Tokens = ag.Tokens.Add(sp.tokens)
416		ag.Messages += sp.messages
417		ag.PartialMessages += sp.partial
418		for _, m := range sp.models.list {
419			ms.add(m)
420		}
421	}
422	
423	// diagnostics builds the line diagnostics; cross is the number of cross-file
424	// duplicates found by finish and extra holds issues that are not the table's.
425	func (t *table) diagnostics(cross int, extra []issueAt) Diagnostics {
426		d := Diagnostics{
427			UnreadableLines: t.unreadable, OversizedLines: t.oversized,
428			NoUsage: t.noUsage, NoMessageID: t.noMessageID, CrossFileDuplicates: cross,
429		}
430		all := append(slices.Clone(t.stateIssues), extra...)
431		for _, s := range t.capped {
432			sorted := slices.Clone(s)
433			slices.SortFunc(sorted, issueAt.compare)
434			all = append(all, sorted[:min(len(sorted), maxFileIssuesPerFile)]...)
435		}
436		slices.SortFunc(all, issueAt.compare)
437		for _, it := range all {
438			d.Files = append(d.Files, it.fi)
439		}
440		return d
441	}
442	
443	// orderedVersions returns the versions by first position.
444	func (t *table) orderedVersions() []string {
445		var vs []string
446		for v := range t.versions {
447			vs = append(vs, v)
448		}
449		slices.SortFunc(vs, func(a, b string) int { return t.versions[a].compare(t.versions[b]) })
450		return vs
451	}
452	
453	// hasLines reports whether t holds anything folded from a complete line.
454	func (t *table) hasLines() bool {
455		if t == nil {
456			return false
457		}
458		return len(t.entries) > 0 || len(t.spill) > 0 || t.unreadable+t.noUsage+t.noMessageID+t.oversized > 0
459	}
460

