241	// Delta is what ReadDelta found since a Cursor: the new complete lines of each
242	// file, already deduplicated, the files that appeared, the meta files that
243	// changed, and the positions to resume from. Paths live in unexported fields
244	// and are never printed.
245	type Delta struct {
246		valid     bool   // false for the zero Delta, which was never read
247		id, seq   uint64 // the cursor it was read from
248		full      bool
249		changed   bool
250		sessionID string
251		files     []fileCursor
252		metas     []metaCursor
253		part      *table
254		parentErr error     // why the parent could not be opened, for ParseSession
255		read      time.Time // when it was read: mtimes are clamped to it
256	}
257	
258	// Full reports whether the delta was read from the start of every file (first
259	// read, Rewound cursor, or a change that was not an append).
260	func (d Delta) Full() bool { return d.full }
261	
262	// Empty reports whether nothing changed: no new complete line, no file added
263	// or gone, no meta change, no change of a file's end-of-file state (an
264	// incomplete last line appearing or disappearing) or of its read issue. A
265	// held-back line that only grows, a persistent issue, or an mtime that alone
266	// moved do not count.
267	func (d Delta) Empty() bool { return !d.changed }
268	
269	// String shows counts only.
270	func (d Delta) String() string {
271		return fmt.Sprintf("agentusage.Delta{full: %t, empty: %t, files: %d}", d.full, d.Empty(), len(d.files))
272	}
273	
274	// GoString shows counts only.
275	func (d Delta) GoString() string { return d.String() }
276	
277	// Aggregate is a session's usage built from successive deltas. It is not safe
278	// for concurrent use: one goroutine (Bubble Tea's Update) owns it.
279	type Aggregate struct {
280		parent    string
281		id, seq   uint64
282		fresh     bool
283		sessionID string
284		files     []fileCursor // parent first, then sub-agents by rank
285		metas     []metaCursor
286		t         *table
287		lastMod   time.Time // newest mtime seen by the last non-empty delta, see Activity
288	}
