290	// String shows counts only: an Aggregate holds paths, and the value receiver
291	// also covers a dereferenced *a.
292	func (a Aggregate) String() string {
293		return fmt.Sprintf("agentusage.Aggregate{files: %d, applied: %d}", len(a.files), a.seq)
294	}
