296	// GoString shows counts only.
297	func (a Aggregate) GoString() string { return a.String() }
298	
299	// NewAggregate starts an empty aggregate for the session whose parent
300	// transcript is parentTranscript (<dir>/<uuid>.jsonl). It does no I/O.
301	func NewAggregate(parentTranscript string) *Aggregate {
302		base := filepath.Base(parentTranscript)
303		return &Aggregate{
304			parent:    parentTranscript,
305			id:        aggregateIDs.Add(1),
306			fresh:     true,
307			sessionID: sanitizeLabel(strings.TrimSuffix(base, transcriptExt)),
308			files:     []fileCursor{newFileCursor(parentTranscript, sanitizeLabel(base), "", parentRank)},
309			t:         newTable(),
310		}
311	}
312	
313	// Cursor returns a copy of the aggregate's position, to hand to ReadDelta.
314	func (a *Aggregate) Cursor() Cursor {
315		return Cursor{
316			parent: a.parent, id: a.id, seq: a.seq, fresh: a.fresh,
317			files: slices.Clone(a.files), metas: slices.Clone(a.metas),
318		}
319	}
320	
321	// Apply folds d in, or replaces everything with it when d.Full(). It returns
322	// ErrStaleDelta, and changes nothing, if d was not read from a.Cursor(). It
323	// takes ownership of d.
324	func (a *Aggregate) Apply(d Delta) error {
325		if !d.valid || d.id != a.id || d.seq != a.seq {
326			return ErrStaleDelta
327		}
328		switch {
329		case d.full:
330			a.t = boundedTable(d.part)
331		case d.part != nil:
332			a.t.mergeCapped(d.part)
333		}
334		a.files, a.metas, a.sessionID = d.files, d.metas, d.sessionID
335		if d.changed {
336			if n := newestMod(d); n.After(a.lastMod) {
337				a.lastMod = n // never moves back when the newest file disappears
338			}
339		}
340		a.fresh = false
341		a.seq++
342		return nil
343	}
344	
345	// boundedTable returns part, or a copy of it holding at most maxNoIDEntries
346	// entries without a message id.
347	func boundedTable(part *table) *table {
348		if part == nil {
349			return newTable()
350		}
351		if part.noID <= maxNoIDEntries {
352			return part
353		}
354		t := newTable()
355		t.mergeCapped(part)
356		return t
357	}
358	
359	// Usage returns the session's usage so far, same shape and rules as
360	// ParseSession; the result shares no memory with the aggregate.
361	func (a *Aggregate) Usage() Usage {
362		agents := []Agent{{Main: true, State: StateUnknown}}
363		var diag Diagnostics
364		var truncated []string
365		var issues []issueAt
366		metaOf := make(map[string]metaCursor, len(a.metas))
367		for _, m := range a.metas {
368			metaOf[m.rank] = m
369		}
370		for _, fc := range a.files {
371			if fc.tail {
372				truncated = append(truncated, fc.name)
373			}
374			if fc.hasIssue {
375				fi := FileIssue{File: fc.name, Offset: fc.issueOff, Kind: fc.issue}
376				issues = append(issues, issueAt{p: pos{rank: fc.rank, off: fc.issueOff}, fi: fi})
377			}
378			if fc.rank != parentRank {
379				agents = append(agents, subAgent(fc, metaOf[fc.rank], &diag))
380			}
381		}
382		agents, diag2, versions := a.t.finishWith(agents, issues)
383		diag2.MetaMissing, diag2.MetaUnreadable, diag2.TruncatedFiles = diag.MetaMissing, diag.MetaUnreadable, truncated
384		return Usage{SessionID: a.sessionID, Agents: agents, Versions: versions, Diagnostics: diag2}
385	}
386	
387	// subAgent builds a sub-agent's identity from its meta cursor, counting a
388	// missing or unreadable meta file in diag.
389	func subAgent(fc fileCursor, m metaCursor, diag *Diagnostics) Agent {
390		ag := Agent{ID: fc.label, key: fc.rank}
391		switch {
392		case m.path == "":
393			diag.MetaMissing++
394		case m.unreadable:
395			diag.MetaUnreadable++
396		default:
397			ag.Type, ag.State, ag.SpawnDepth = m.typ, m.state, m.depth
398		}
399		return ag
400	}
401	
402	// ReadDelta lists the session again (parent, subagents/, meta files, Lstat
403	// only) and reads what was appended since c. Files whose size did not change
404	// are not opened. It fails only if the session cannot be listed; errors name
405	// base names only, and on error there is nothing to apply. A parent that is
406	// missing, a link or not a regular file is an error. Only a failure to open a
407	// listed file (for example chmod 000), or a removal between the Lstat and the
408	// open, yields an IssueOpenFailed without an error (Full at tick 0, then Empty
409	// while it persists), which the caller can detect through FileIssue.
410	//
411	// When ReadDelta returns an error the caller must not treat the session as
412	// Settled: Activity keeps its last state and says nothing about the failure.
413	//
414	// Declared oracle gap (meta files): a meta file that cannot be read (chmod 000)
415	// counts as MetaUnreadable here, whereas ParseSession(LocateSession) counts it
416	// MetaMissing. Meta files are compared by Lstat size and mtime (D7), so an
417	// unreadable meta stays so after chmod +r until it is rewritten.
418	func ReadDelta(c Cursor) (Delta, error) {
419		files, infos, err := listForPoll(c.parent)
420		if err != nil {
421			return Delta{}, err
422		}
423		return readSession(files, infos, c, timeNow()), nil
424	}
425	
426	// listForPoll lists the session like LocateSession, with meta presence from
427	// Lstat only (D7), and returns the Lstat result of each meta file found.
428	func listForPoll(parent string) (SessionFiles, map[string]os.FileInfo, error) {
429		infos := map[string]os.FileInfo{}
430		files, err := locateSession(parent, func(path string) bool {
431			fi, err := os.Lstat(path)
432			if err != nil || !fi.Mode().IsRegular() {
433				return false
434			}
435			infos[path] = fi
436			return true
437		})
438		return files, infos, err
439	}
440	
441	// target is one transcript of a listing, with its meta file ("" if absent).
442	type target struct {
443		fc   fileCursor
444		meta string
445	}
446	
447	// sessionTargets turns a listing into fresh cursors: the parent first, then
448	// the sub-agents in rank order, which is the order ParseSession reads them.
449	func sessionTargets(files SessionFiles) []target {
450		out := []target{{fc: newFileCursor(files.Parent, sanitizeLabel(filepath.Base(files.Parent)), "", parentRank)}}
451		for _, sa := range files.SubAgents {
452			id := sanitizeLabel(sa.ID)
453			name := sanitizeLabel(filepath.Base(sa.Transcript))
454			rank := transcriptRank(id, name, sa.ID, sa.Transcript)
455			fc := newFileCursor(sa.Transcript, name, rank, rank)
456			fc.label = id
457			out = append(out, target{fc: fc, meta: sa.Meta})
458		}
459		slices.SortFunc(out[1:], func(a, b target) int { return cmp.Compare(a.fc.rank, b.fc.rank) })
460		return out
461	}
462	
463	// readSession reads the files of a listing from c. A change that is not an
464	// append (D4) restarts every file from the start and the delta is Full.
465	// ParseSession passes a fresh cursor and no meta Lstat information.
466	func readSession(files SessionFiles, infos map[string]os.FileInfo, c Cursor, now time.Time) Delta {
467		targets := sessionTargets(files)
468		full := c.fresh
469		p, ok := readTargets(targets, c, now)
470		if !ok {
471			c, full = c.Rewound(), true
472			// ok is true by construction: a rewound cursor knows no file, so no
473			// file can ask for another restart.
474			p, _ = readTargets(targets, c, now)
475		}
476		metas, metaChanged := readMetas(targets[1:], infos, c)
477		return Delta{
478			valid: true, id: c.id, seq: c.seq, full: full,
479			changed:   full || p.changed || metaChanged,
480			sessionID: sanitizeLabel(files.ID),
481			files:     p.files, metas: metas, part: p.part, parentErr: p.parentErr, read: now,
482		}
483	}
484	
485	// sessionPass is the outcome of one pass over the transcripts.
486	type sessionPass struct {
487		files     []fileCursor
488		part      *table
489		changed   bool
490		parentErr error
491	}
492	
493	// readTargets reads every target from its cursor in c, or from the start when
494	// c does not know it. ok is false when a file asks for a restart (D4): a
495	// file read before is gone, or was not simply appended to.
496	func readTargets(targets []target, c Cursor, now time.Time) (sessionPass, bool) {
497		prior := make(map[string]fileCursor, len(c.files))
498		for _, fc := range c.files {
499			prior[fc.rank] = fc
500		}
501		var p sessionPass
502		for _, tg := range targets {
503			fc, had := prior[tg.fc.rank]
504			delete(prior, tg.fc.rank)
505			if !had {
506				fc, p.changed = tg.fc, true
507			}
508			fr := readFile(fc, now)
509			if fr.reset {
510				return sessionPass{}, false
511			}
512			if fr.next.rank == parentRank && fr.err != nil {
513				p.parentErr = fr.err
514			}
515			p.changed = p.changed || fr.part.hasLines() || fc.issueState() != fr.next.issueState() ||
516				fc.tail != fr.next.tail
517			p.files = append(p.files, fr.next)
518			p.addPart(fr.part)
519		}
520		for _, gone := range prior {
521			if gone.read() {
522				return sessionPass{}, false
523			}
524			p.changed = true
525		}
526		return p, true
527	}
528	
529	// addPart folds the lines of one file into the pass, spilling no-id lines past
530	// maxNoIDEntries like a sequential read does (totals stay exact).
531	func (p *sessionPass) addPart(part *table) {
532		switch {
533		case part == nil:
534		case p.part == nil:
535			p.part = part
536		default:
537			p.part.mergeCapped(part) // keeps the pass within the no-id bound across files
538		}
539	}
540	
541	// issueState is what a cursor says about its last read, for comparisons.
542	type issueState struct {
543		has  bool
544		kind IssueKind
545		off  int64
546	}
547	
548	func (fc fileCursor) issueState() issueState {
549		return issueState{has: fc.hasIssue, kind: fc.issue, off: fc.issueOff}
550	}
551	
552	// readMetas returns the meta cursors of the sub-agents in targets, reading a
553	// meta file only when its Lstat size or mtime differs from c's (D7), and
554	// whether any of them tells something new. An unreadable meta file is
555	// MetaUnreadable here but MetaMissing for ParseSession(LocateSession): a
556	// declared oracle gap, see ReadDelta.
557	func readMetas(subs []target, infos map[string]os.FileInfo, c Cursor) ([]metaCursor, bool) {
558		prior := make(map[string]metaCursor, len(c.metas))
559		for _, m := range c.metas {
560			prior[m.rank] = m
561		}
562		out := make([]metaCursor, 0, len(subs))
563		changed := false
564		for _, tg := range subs {
565			m := nextMeta(tg, infos, prior)
566			old, had := prior[m.rank]
567			changed = changed || !had || !old.sameResult(m)
568			out = append(out, m)
569		}
570		return out, changed
571	}
572	
573	// nextMeta returns the meta cursor of one sub-agent: the prior one when its
574	// file did not change, else a fresh read through readMetaFile.
575	func nextMeta(tg target, infos map[string]os.FileInfo, prior map[string]metaCursor) metaCursor {
576		m := metaCursor{rank: tg.fc.rank}
577		if tg.meta == "" {
578			return m
579		}
580		m.path = tg.meta
581		fi := infos[tg.meta]
582		if fi != nil {
583			m.size, m.modTime = fi.Size(), fi.ModTime()
584		}
585		if old, ok := prior[m.rank]; ok && old.unchangedSince(tg.meta, fi) {
586			return old
587		}
588		md, err := readMetaFile(tg.meta)
589		if err != nil {
590			m.unreadable = true
591			return m
592		}
593		m.typ, m.state, m.depth = md.AgentType, md.state(), md.SpawnDepth
594		return m
595	}
596	
597	// newestMod returns the newest mtime among the files and metas of d, clamped
598	// to the time d was read.
599	func newestMod(d Delta) time.Time {
600		var newest time.Time
601		for _, fc := range d.files {
602			if fc.modTime.After(newest) {
603				newest = fc.modTime
604			}
605		}
606		for _, m := range d.metas {
607			if m.modTime.After(newest) {
608				newest = m.modTime
609			}
610		}
611		if newest.After(d.read) {
612			newest = d.read
613		}
614		return newest
615	}
616	
617	// Activity tells a poller when a session has gone quiet. It holds times and
618	// counts only, never a path.
619	type Activity struct {
620		// LastChange is the newest mtime among the parent, the sub-agents and the
621		// metas as of the last read that found a change, capped at that read's
622		// time. Zero before the first Apply. An empty delta does not advance it.
623		LastChange time.Time
624		// Unfinished counts sub-agents whose meta says finished: false.
625		Unfinished int
626		// failing is set while any transcript (parent or sub-agent) cannot be
627		// opened or read (IssueOpenFailed, IssueReadError).
628		failing bool
629	}
630	
631	// Settled reports whether polling can stop: something was applied, no
632	// transcript is failing to open or read (the poller keeps trying), no
633	// sub-agent is unfinished, and nothing changed for at least quiet before now.
634	// If ReadDelta returned an error, the caller must not consider the session
635	// Settled: Activity then holds the last applied state.
636	func (a Activity) Settled(now time.Time, quiet time.Duration) bool {
637		return !a.LastChange.IsZero() && !a.failing && a.Unfinished == 0 && now.Sub(a.LastChange) >= quiet
638	}
639	
640	// Activity returns what the reads applied so far say about the session's life.
641	func (a *Aggregate) Activity() Activity {
642		act := Activity{LastChange: a.lastMod}
643		for _, m := range a.metas {
644			if m.path != "" && !m.unreadable && m.state == StateUnfinished {
645				act.Unfinished++
646			}
647		}
648		for _, f := range a.files {
649			if f.hasIssue && (f.issue == IssueOpenFailed || f.issue == IssueReadError) {
650				act.failing = true
651				break
652			}
653		}
654		return act
655	}
