package agentusageview

import (
	"fmt"
	"sync"
	"time"

	tea "github.com/charmbracelet/bubbletea"

	"github.com/anthnel/devdesk/internal/agentusage"
)

// listSessionsCmd resolves the projects root and lists it, all inside the Cmd:
// the model is not touched (Rule 110) and the answer carries gen back.
func listSessionsCmd(gen int) tea.Cmd {
	return func() tea.Msg {
		root, err := agentusage.ProjectsRoot()
		if err != nil {
			return sessionListLoadedMsg{gen: gen, err: err}
		}
		listing, err := agentusage.ListSessions(root)
		return sessionListLoadedMsg{gen: gen, root: root, listing: listing, err: err}
	}
}

// pollInterval is the pause between two reads of the open session; a variable
// so tests can shorten it. quietPeriod is how long a session must be quiet to
// be considered settled and no longer polled.
var (
	pollInterval = 2 * time.Second
	quietPeriod  = 5 * time.Minute
)

// now is the clock the poll chain reads, replaceable in tests.
var now = time.Now

// usageDeltaMsg carries one incremental read. gen is agentGen at the time the
// read started; at is when it finished.
type usageDeltaMsg struct {
	gen   int
	delta agentusage.Delta
	err   error
	at    time.Time
}

// String and GoString keep the delta's paths out of any formatted dump: fmt
// cannot call the Delta's own redacting methods through an unexported field.
func (m usageDeltaMsg) String() string {
	return fmt.Sprintf("usageDeltaMsg{gen: %d, delta: %v, failed: %t}", m.gen, m.delta, m.err != nil)
}

// GoString is String.
func (m usageDeltaMsg) GoString() string { return m.String() }

// usagePollTickMsg says the poll interval of generation gen has elapsed.
type usagePollTickMsg struct{ gen int }

// agentsResumeMsg asks Update to restart a poll chain that stopped.
type agentsResumeMsg struct{}

// readDeltaCmd reads what changed since c. It owns its Cursor copy and touches
// no model (Rule 110); the answer carries gen and the time of the read.
func readDeltaCmd(gen int, c agentusage.Cursor) tea.Cmd {
	return func() tea.Msg {
		delta, err := agentusage.ReadDelta(c)
		return usageDeltaMsg{gen: gen, delta: delta, err: err, at: now()}
	}
}

// pollTickCmd waits pollInterval, then answers with a tick of generation gen.
// The interval is read when the Cmd is built (Update's goroutine), never from
// the Cmd's own. The Cmd may be run twice (a caller inspecting it, then
// running it): the wait happens once and the answer is kept.
func pollTickCmd(gen int) tea.Cmd {
	d := pollInterval
	var once sync.Once
	return func() tea.Msg {
		once.Do(func() { time.Sleep(d) })
		return usagePollTickMsg{gen: gen}
	}
}

// resumeCmd answers agentsResumeMsg at once.
func resumeCmd() tea.Cmd {
	return func() tea.Msg { return agentsResumeMsg{} }
}

package agentusageview

import (
	"fmt"
	"slices"
	"strings"

	"github.com/anthnel/devdesk/internal/agentusage"
)

// mainKey is the key of the orchestrator, of which a session has one.
const mainKey = "main"

// agentKeys names agents so the same one keeps its key from one rebuild to the
// next: "main" for the orchestrator, "sub:<ID>#n" for a sub-agent, n counting
// the earlier agents that share its ID (an ID is not guaranteed unique). It
// must be given the canonical order (agentRows), never the sorted or filtered
// one: under a sort, two twins would trade keys whenever they trade ranks.
func agentKeys(agents []agentusage.Agent) []string {
	seen := make(map[string]int, len(agents))
	keys := make([]string, len(agents))
	for i, a := range agents {
		if a.Main {
			keys[i] = mainKey
			continue
		}
		keys[i] = fmt.Sprintf("sub:%s#%d", a.ID, seen[a.ID])
		seen[a.ID]++
	}
	return keys
}

// populationOf lists what makes a table "another population" for the column
// widths: which agents it holds, and the models each one names. Counts change
// on every delta and do not count. A type can change too (its meta arrives
// after the transcript) but stays out on purpose: the column is remeasured at
// the next ctrl+r or change of population.
func populationOf(rows []agentRow) []string {
	out := make([]string, len(rows))
	for i, r := range rows {
		out[i] = r.key + "|" + strings.Join(r.Models, ",")
	}
	return out
}

// withUsage shows u in the agents table, keeping the cursor on the agent it was
// on (whatever the filter and the sort do to the order), and clears the
// loading and error states. The columns are remeasured only on a full read or
// when the population changed, so a two-second delta never reshuffles them.
func (m Model) withUsage(u agentusage.Usage, full bool) Model {
	before := populationOf(m.agentTable.Items())
	selected, hadSelection := m.selectedAgentKey()
	cursor := m.agentTable.Cursor()

	rows := agentRows(u, m.agentsTree())
	m.usage = u
	m.agentsLoading, m.agentsErr = false, false
	m.agentTable.SetItems(rows)

	if full || !slices.Equal(before, populationOf(rows)) {
		m.agentTable.Remeasure()
	}
	m.agentTable.SetCursor(cursor) // clamps when the agent vanished
	if hadSelection {
		m.selectAgentKey(selected)
	}
	return m
}

// selectAgentKey moves the cursor onto the visible row with that key, if any.
func (m *Model) selectAgentKey(key string) {
	if i := slices.IndexFunc(m.agentTable.Visible(), func(r agentRow) bool { return r.key == key }); i >= 0 {
		m.agentTable.SetCursor(i)
	}
}

// selectedAgentKey is the key of the row under the cursor.
func (m Model) selectedAgentKey() (string, bool) {
	r, ok := m.agentTable.Selected()
	return r.key, ok
}

package agentusageview

import "github.com/anthnel/devdesk/internal/ui/help"

// GetHelpContent returns the help for `?` (Rule 114).
func (m Model) GetHelpContent() help.Content {
	return help.Content{
		Title: "Agent usage",
		Description: "The Claude Code sessions found on this machine, newest first. " +
			"Only where and when a session ran is read — nothing a session says.",
		KeyBindings: []help.KeyBinding{
			{Key: "ctrl+r", Description: "Re-read the whole session from the start (at the sessions level: read the sessions again)"},
			{Key: "→/enter", Description: "Open the selected session's agents"},
			{Key: "←/esc", Description: "Back to the sessions"},
			{Key: "/", Description: "Filter by project or session ID"},
			{Key: ".", Description: "Cycle the sort column (agents: tree, Total largest first, Total smallest first)"},
			{Key: "ctrl+p", Description: "Open command mode"},
			{Key: "?", Description: "Show this help"},
		},
		Sections: []help.Section{
			{
				Title: "Columns",
				Body: "Project: the working directory the session ran in, with your home folded to ~. " +
					"A long path is cut from the left so the project's own name stays visible; a dash means the transcript named none.\n" +
					"Last active: when the session's transcript was last written, in local time.\n" +
					"Session: the start of the session ID. The filter matches the full ID.",
			},
			{
				Title: "Where sessions come from",
				Body: "Claude Code keeps one transcript per session under projects/ in its configuration directory: " +
					"$CLAUDE_CONFIG_DIR when set, otherwise ~/.claude. " +
					"Claude Code deletes old transcripts itself (after 30 days by default), so older sessions disappear from here too.\n" +
					"Sessions that could not be listed (symbolic links, which are refused rather than followed, unreadable directories, " +
					"or sessions beyond the listing cap) are counted as Skipped in the header.",
			},
			{
				Title: "Agents",
				Body: "Opening a session lists its agents: the orchestrator first, then each sub-agent with its type, " +
					"as a tree, with the models used and the tokens in, out, and cached.\n" +
					"A ≥ before an Out count means a floor: that sub-agent's transcript was still being written, so the real figure is higher.\n" +
					"The orchestrator is the main conversation; its figures are never a floor.\n" +
					"When part of a transcript could not be read, the footer says the totals are approximate.",
			},
			{
				Title: "Agent columns",
				Body: "Agent: the orchestrator, or the sub-agent's type. ID: the start of the sub-agent's ID, long enough to tell two agents of the same type apart; " +
					"the orchestrator shows a dash. The filter matches the full ID.\n" +
					"Model, In, Out, Cache read, Cache write, Total: models used and token counts. " +
					"On a narrow terminal Cache write goes first, then Cache read, In, and Model. Agent, ID, Out, Total and Share stay.\n" +
					"Share: the agent's part of the session total, to one decimal, rounded down. " +
					"The orchestrator takes the rounding remainder, so the column adds up to 100%. A dash means the session has no tokens.\n" +
					"Press . to cycle: tree, then Total largest first, then Total smallest first, then the tree again. " +
					"Sorted, the list is flat: the branches go away. The sort stays when you open another session or press ctrl+r.",
			},
			{
				Title: "Live updates",
				Body: "While a session is open and still active, its figures are refreshed every 2 s and the header shows Updates: live.\n" +
					"Updates pause after 5 min without activity once every agent has finished (a session with an unfinished sub-agent stays live), or when its transcript is deleted: the header shows Updates: paused.\n" +
					"Press ctrl+r to resume. Re-read the whole session from the start with ctrl+r; coming back to the view only reads what changed since the last point read, and goes back to live if the session is being written to.\n" +
					"The list of sessions itself is not live: refresh it with ctrl+r at the sessions level.",
			},
			{
				Title: "Privacy",
				Body: "The sessions list reads the working directory and the file date alone. " +
					"Opening a session also reads its token counts, model names and agent types, and shows only the project's working directory, the date, the session ID, the agent types, the models and the tokens. " +
					"Prompts, replies, tool output and the paths of files a session touched are never displayed and never logged.",
			},
		},
	}
}

