1	package agentusageview
2	
3	import (
4		"fmt"
5		"sort"
6		"strings"
7	
8		"github.com/charmbracelet/lipgloss"
9	
10		"github.com/anthnel/devdesk/internal/agentusage"
11		"github.com/anthnel/devdesk/internal/ui/datatable"
12		"github.com/anthnel/devdesk/internal/ui/theme"
13	)
14	
15	const (
16		// noValue is the dash of a cell with nothing to show.
17		noValue = "-"
18		// noModel stands for an agent whose transcript named no model.
19		noModel = noValue
20		// unknownID stands for a sub-agent whose ID is empty, so it cannot be
21		// mistaken for the orchestrator, which has no short ID by design.
22		unknownID = "?"
23		// unknownType stands for a sub-agent whose meta file gave no type.
24		unknownType = "unknown"
25		// orchestratorLabel is the Agent cell of the main agent.
26		orchestratorLabel = "orchestrator"
27		// partialMark prefixes an output count that is a floor, not an exact value.
28		partialMark = "≥ "
29		// stem and lastStem draw the tree branch in front of a sub-agent's type.
30		stem     = "├─ "
31		lastStem = "└─ "
32	)
33	
34	// agentIDPrefix is the shortest agent ID shown.
35	const agentIDPrefix = 8
36	
37	// agentRow is one line of the agents table.
38	type agentRow struct {
39		agentusage.Agent
40		branch  string // stem, lastStem, or "" (orchestrator, or a sorted list)
41		shortID string // ID prefix, distinct within the session; "" for the orchestrator
42		share   int    // tenths of a percent of the session total, or noShare
43		key     string // identity across rebuilds, see agentKeys
44	}
45	
46	// agentRows orders a session's agents (orchestrator, then sub-agents by ID),
47	// gives each its short ID and share, and draws the branches when tree is true.
48	// The sort is stable so equal IDs keep their input order.
49	func agentRows(u agentusage.Usage, tree bool) []agentRow {
50		var main, subs []agentusage.Agent
51		for _, a := range u.Agents {
52			if a.Main {
53				main = append(main, a)
54			} else {
55				subs = append(subs, a)
56			}
57		}
58		sort.SliceStable(subs, func(i, j int) bool { return subs[i].ID < subs[j].ID })
59	
60		ordered := append(append([]agentusage.Agent{}, main...), subs...)
61		totals := make([]int64, len(ordered))
62		for i, a := range ordered {
63			totals[i] = a.Tokens.Total()
64		}
65		mainIdx := -1
66		if len(main) > 0 {
67			mainIdx = 0
68		}
69		parts := shares(totals, u.Total().Total(), mainIdx)
70	
71		ids := make([]string, len(subs))
72		for i, a := range subs {
73			ids[i] = a.ID
74		}
75		short := shortAgentIDs(ids)
76	
77		keys := agentKeys(ordered)
78		rows := make([]agentRow, 0, len(ordered))
79		for i, a := range ordered {
80			row := agentRow{Agent: a, share: parts[i], key: keys[i]}
81			if !a.Main {
82				j := i - len(main)
83				row.shortID = short[j]
84				if tree {
85					row.branch = stem
86					if j == len(subs)-1 {
87						row.branch = lastStem
88					}
89				}
90			}
91			rows = append(rows, row)
92		}
93		return rows
94	}
95	
96	// shortAgentIDs cuts every ID to one common length, the smallest n >=
97	// agentIDPrefix (in runes) at which all of them differ, capped at each ID's
98	// own length.
99	func shortAgentIDs(ids []string) []string {
100		if len(ids) == 0 {
101			return nil
102		}
103		longest := 0
104		runes := make([][]rune, len(ids))
105		for i, id := range ids {
106			runes[i] = []rune(id)
107			longest = max(longest, len(runes[i]))
108		}
109		cut := func(n int) []string {
110			out := make([]string, len(runes))
111			for i, r := range runes {
112				out[i] = string(r[:min(n, len(r))])
113			}
114			return out
115		}
116		for n := agentIDPrefix; n < longest; n++ {
117			seen := make(map[string]bool, len(ids))
118			distinct := true
119			for _, s := range cut(n) {
120				if seen[s] {
121					distinct = false
122					break
123				}
124				seen[s] = true
125			}
126			if distinct {
127				return cut(n)
128			}
129		}
130		return cut(longest)
131	}
132	
133	// agentColumns describes the agents table. Only Total sorts, largest first;
134	// without a sort the order is the tree. Columns give way on a narrow terminal
135	// in this order: Cache write, Cache read, In, Model. The ID never does, so two
136	// agents of one type stay apart.
137	func agentColumns() []datatable.Column[agentRow] {
138		count := func(title string, width int, tokens func(agentRow) int64) datatable.Column[agentRow] {
139			return datatable.Column[agentRow]{
140				Title: title, Sizing: datatable.SizingFixed, MinWidth: width,
141				Cell:  func(r agentRow) string { return formatTokens(tokens(r)) },
142				Style: func(r agentRow) lipgloss.Style { return dimWhen(tokens(r) == 0) },
143			}
144		}
145		in := count("In", 6, func(r agentRow) int64 { return r.Tokens.Input })
146		in.Optional = true
147		cacheRead := count("Cache read", len("Cache read"), func(r agentRow) int64 { return r.Tokens.CacheRead })
148		cacheRead.Optional = true
149		cacheWrite := count("Cache write", len("Cache write"), func(r agentRow) int64 { return r.Tokens.CacheWrite })
150		cacheWrite.Optional, cacheWrite.DropFirst = true, true
151		total := count("Total", 6, func(r agentRow) int64 { return r.Tokens.Total() })
152		total.Less = func(a, b agentRow) bool { return a.Tokens.Total() < b.Tokens.Total() }
153		total.DescFirst = true
154	
155		out := count("Out", 7, nil)
156		out.Cell = outCell
157		out.Style = func(r agentRow) lipgloss.Style { return dimWhen(r.Tokens.Output == 0) }
158	
159		return []datatable.Column[agentRow]{
160			{Title: "Agent", Sizing: datatable.SizingContent, MinWidth: 14, Cell: roleCell, Search: agentSearch,
161				Style: func(r agentRow) lipgloss.Style { return dimWhen(!r.Main && r.Type == "") }},
162			{Title: "ID", Sizing: datatable.SizingContent, MinWidth: agentIDPrefix, Cell: idCell,
163				Search: func(r agentRow) string { return r.ID },
164				Style:  func(r agentRow) lipgloss.Style { return dimWhen(idCell(r) == noValue || idCell(r) == unknownID) }},
165			{Title: "Model", Sizing: datatable.SizingContent, MinWidth: 12, Flex: 2, Optional: true, Cell: modelsCell, Search: modelsCell,
166				Style: func(r agentRow) lipgloss.Style { return dimWhen(len(r.Models) == 0) }},
167			in, out, cacheRead, cacheWrite, total,
168			{Title: "Share", Sizing: datatable.SizingFixed, MinWidth: len("100.0%"), Cell: shareCell,
169				Style: func(r agentRow) lipgloss.Style { return dimWhen(r.share <= 0) }},
170		}
171	}
172	
173	// dimWhen is Rule 122's colour discipline: a zero or a placeholder is dim,
174	// anything else keeps the default colour.
175	func dimWhen(dim bool) lipgloss.Style {
176		if dim {
177			return theme.DimStyle
178		}
179		return lipgloss.NewStyle()
180	}
181	
182	// agentSearch is what `/` matches in the Agent column: the role. The full ID is
183	// searched through the ID column.
184	func agentSearch(r agentRow) string { return roleCell(r) }
185	
186	// idCell is the ID column: the short ID of a sub-agent, a dash for the
187	// orchestrator, which has none.
188	func idCell(r agentRow) string {
189		switch {
190		case r.Main:
191			return noValue
192		case r.shortID == "":
193			return unknownID
194		}
195		return r.shortID
196	}
197	
198	// shareCell is the Share column.
199	func shareCell(r agentRow) string { return formatShare(r.share) }
200	
201	// roleCell is the Agent cell: "orchestrator", or the sub-agent's type behind
202	// its branch.
203	func roleCell(r agentRow) string {
204		if r.Main {
205			return orchestratorLabel
206		}
207		typ := r.Type
208		if typ == "" {
209			typ = unknownType
210		}
211		return r.branch + typ
212	}
213	
214	// modelsCell lists the models the agent used.
215	func modelsCell(r agentRow) string {
216		if len(r.Models) == 0 {
217			return noModel
218		}
219		return strings.Join(r.Models, ", ")
220	}
221	
222	// outCell is the output count. A sub-agent still being written is a floor and
223	// says so; the orchestrator never does, its transcript is the one being read.
224	func outCell(r agentRow) string {
225		out := formatTokens(r.Tokens.Output)
226		if !r.Main && r.PartialOutput() {
227			return partialMark + out
228		}
229		return out
230	}
231	
232	// formatTokens renders a count compactly, floored to one decimal: 1099 is
233	// "1.0k", never "1.1k". From 100 of a unit up the decimal is dropped.
234	func formatTokens(n int64) string {
235		units := []struct {
236			size   int64
237			suffix string
238		}{
239			{1_000_000_000_000, "T"}, {1_000_000_000, "B"}, {1_000_000, "M"}, {1_000, "k"},
240		}
241		for _, u := range units {
242			if n < u.size {
243				continue
244			}
245			tenths := n / (u.size / 10) // divide first: n*10 would overflow
246			if tenths >= 1000 {
247				return fmt.Sprintf("%d%s", tenths/10, u.suffix)
248			}
249			return fmt.Sprintf("%d.%d%s", tenths/10, tenths%10, u.suffix)
250		}
251		return fmt.Sprintf("%d", n)
252	}
253

