1	package agentusageview
2	
3	import (
4		"fmt"
5		"sync"
6		"time"
7	
8		tea "github.com/charmbracelet/bubbletea"
9	
10		"github.com/anthnel/devdesk/internal/agentusage"
11	)
12	
13	// listSessionsCmd resolves the projects root and lists it, all inside the Cmd:
14	// the model is not touched (Rule 110) and the answer carries gen back.
15	func listSessionsCmd(gen int) tea.Cmd {
16		return func() tea.Msg {
17			root, err := agentusage.ProjectsRoot()
18			if err != nil {
19				return sessionListLoadedMsg{gen: gen, err: err}
20			}
21			listing, err := agentusage.ListSessions(root)
22			return sessionListLoadedMsg{gen: gen, root: root, listing: listing, err: err}
23		}
24	}
25	
26	// pollInterval is the pause between two reads of the open session; a variable
27	// so tests can shorten it. quietPeriod is how long a session must be quiet to
28	// be considered settled and no longer polled.
29	var (
30		pollInterval = 2 * time.Second
31		quietPeriod  = 5 * time.Minute
32	)
33	
34	// now is the clock the poll chain reads, replaceable in tests.
35	var now = time.Now
36	
37	// usageDeltaMsg carries one incremental read. gen is agentGen at the time the
38	// read started; at is when it finished.
39	type usageDeltaMsg struct {
40		gen   int
41		delta agentusage.Delta
42		err   error
43		at    time.Time
44	}
45	
46	// String and GoString keep the delta's paths out of any formatted dump: fmt
47	// cannot call the Delta's own redacting methods through an unexported field.
48	func (m usageDeltaMsg) String() string {
49		return fmt.Sprintf("usageDeltaMsg{gen: %d, delta: %v, failed: %t}", m.gen, m.delta, m.err != nil)
50	}
51	
52	// GoString is String.
53	func (m usageDeltaMsg) GoString() string { return m.String() }
54	
55	// usagePollTickMsg says the poll interval of generation gen has elapsed.
56	type usagePollTickMsg struct{ gen int }
57	
58	// agentsResumeMsg asks Update to restart a poll chain that stopped.
59	type agentsResumeMsg struct{}
60	
61	// readDeltaCmd reads what changed since c. It owns its Cursor copy and touches
62	// no model (Rule 110); the answer carries gen and the time of the read.
63	func readDeltaCmd(gen int, c agentusage.Cursor) tea.Cmd {
64		return func() tea.Msg {
65			delta, err := agentusage.ReadDelta(c)
66			return usageDeltaMsg{gen: gen, delta: delta, err: err, at: now()}
67		}
68	}
69	
70	// pollTickCmd waits pollInterval, then answers with a tick of generation gen.
71	// The interval is read when the Cmd is built (Update's goroutine), never from
72	// the Cmd's own. The Cmd may be run twice (a caller inspecting it, then
73	// running it): the wait happens once and the answer is kept.
74	func pollTickCmd(gen int) tea.Cmd {
75		d := pollInterval
76		var once sync.Once
77		return func() tea.Msg {
78			once.Do(func() { time.Sleep(d) })
79			return usagePollTickMsg{gen: gen}
80		}
81	}
82	
83	// resumeCmd answers agentsResumeMsg at once.
84	func resumeCmd() tea.Cmd {
85		return func() tea.Msg { return agentsResumeMsg{} }
86	}
87

1	package agentusageview
2	
3	import (
4		"path/filepath"
5		"strconv"
6	
7		"github.com/charmbracelet/lipgloss"
8	
9		sharedcomponents "github.com/anthnel/devdesk/internal/ui/components"
10		"github.com/anthnel/devdesk/internal/ui/shortcut"
11		"github.com/anthnel/devdesk/internal/ui/theme"
12	)
13	
14	// baseFooterHeight is the blank line and the message line (Rule 124).
15	const baseFooterHeight = 2
16	
17	// View is the table, whatever it holds (Rule 139).
18	func (m Model) View() string {
19		if m.level == levelAgents {
20			return m.agentTable.View()
21		}
22		return m.table.View()
23	}
24	
25	// GetTitle names the view, and the project of the open session at the agents
26	// level (its short ID when the transcript named no project).
27	func (m Model) GetTitle() string {
28		title := theme.IconAgentUsage + " Agent usage"
29		if m.level != levelAgents {
30			return title
31		}
32		leaf := shortID(m.open.ID)
33		if m.open.Project != "" {
34			leaf = filepath.Base(m.open.Project)
35		}
36		return title + " › " + leaf
37	}
38	
39	// shortID is the start of a session ID, as the Session column shows it.
40	func shortID(id string) string {
41		r := []rune(id)
42		return string(r[:min(sessionIDPrefix, len(r))])
43	}
44	
45	// GetIcon returns nothing: the title carries the icon.
46	func (m Model) GetIcon() string { return "" }
47	
48	// GetHeaderInfo counts the sessions on screen, and the ones not listed when
49	// there are some.
50	func (m Model) GetHeaderInfo(_ string) []shortcut.HeaderInfo {
51		if m.level == levelAgents {
52			return m.agentsHeaderInfo()
53		}
54		info := []shortcut.HeaderInfo{
55			{Key: "Sessions", Value: strconv.Itoa(len(m.table.Visible())), Style: theme.HeaderValueStyle},
56		}
57		if m.omitted > 0 {
58			info = append(info, shortcut.HeaderInfo{Key: "Skipped", Value: strconv.Itoa(m.omitted), Style: theme.HeaderValueStyle})
59		}
60		return info
61	}
62	
63	// agentsHeaderInfo counts the agents on screen and their tokens, both following
64	// the filter.
65	func (m Model) agentsHeaderInfo() []shortcut.HeaderInfo {
66		rows := m.agentTable.Visible()
67		var total int64
68		for _, r := range rows {
69			total += r.Tokens.Total()
70		}
71		return []shortcut.HeaderInfo{
72			{Key: "Agents", Value: strconv.Itoa(len(rows)), Style: theme.HeaderValueStyle},
73			{Key: "Tokens", Value: formatTokens(total), Style: theme.HeaderValueStyle},
74			{Key: "Updates", Value: m.updatesState(), Style: theme.HeaderValueStyle},
75		}
76	}
77	
78	// updatesState says whether the open session is polled: live while the chain
79	// runs, paused once it stopped (settled session, deleted transcript).
80	func (m Model) updatesState() string {
81		if m.level == levelAgents && m.agg != nil && !m.pollStopped {
82			return "live"
83		}
84		return "paused"
85	}
86	
87	// GetShortcuts returns the same keys at both levels and in every state; what
88	// varies is Disabled, from the one availability the handlers also read
89	// (Rule 130).
90	func (m Model) GetShortcuts() shortcut.Shortcuts {
91		a := m.availability()
92		return shortcut.Shortcuts{
93			{Key: "ctrl+r", Description: "Refresh"},
94			{Key: "→", Description: "Open agents", Disabled: !a.Open.Enabled()},
95			{Key: "esc", Description: "Go back", Disabled: !a.Close.Enabled()},
96			{Key: "/", Description: "Filter"},
97			{Key: ".", Description: "Sort"},
98			{Key: "?", Description: "Help"},
99		}
100	}
101	
102	// GetFooterHeight budgets the footer (Rules 124, 136).
103	func (m Model) GetFooterHeight() int {
104		h := baseFooterHeight + m.activeFilterBar().ExtraHeight()
105		if m.level == levelAgents {
106			h++ // the breadcrumb row
107		}
108		return h
109	}
110	
111	// RenderFooter renders the breadcrumb at the agents level, the filter bar when
112	// visible, a blank line, and the message line.
113	func (m Model) RenderFooter(width int) string {
114		line := theme.EmptyLineBg(width) + "\n" + m.footer.View(width, m.status())
115		if bar := m.activeFilterBar(); bar.IsVisible() {
116			line = bar.View() + "\n" + line
117		}
118		if m.level == levelAgents {
119			line = m.breadcrumb(width) + "\n" + line
120		}
121		return line
122	}
123	
124	// breadcrumb is Sessions › project › ID, the last one active and its parents
125	// dim, with the one cell of left padding Rule 123 asks for.
126	func (m Model) breadcrumb(width int) string {
127		project := noProject
128		if m.open.Project != "" {
129			project = theme.ShortPath(m.open.Project, max(width/2, 1))
130		}
131		base := lipgloss.NewStyle().Background(theme.ColorBackground)
132		parents := base.Foreground(theme.ColorDim).Render("Sessions › " + project + " › ")
133		active := base.Foreground(theme.ColorSecondary).Bold(true).Render(shortID(m.open.ID))
134		return theme.PadWithBg(theme.Bg(" ")+parents+active, width)
135	}
136	
137	// status is derived on every frame, with no timer (Rule 128).
138	//
139	// The empty sentence needs the listing to be empty in total, not after the
140	// filter: a filter with no match is not a machine with no sessions.
141	func (m Model) status() sharedcomponents.Status {
142		if m.level == levelAgents {
143			return m.agentsStatus()
144		}
145		switch {
146		case m.loadErr:
147			return sharedcomponents.Status{
148				Text:  "Failed to list Claude Code sessions — check logs",
149				Level: sharedcomponents.LevelError,
150			}
151		case m.loading:
152			return sharedcomponents.Status{Text: "Reading Claude Code sessions...", Spinner: true}
153		case len(m.table.Items()) == 0:
154			return sharedcomponents.Status{Text: "No Claude Code sessions found in " + theme.FoldHome(m.root)}
155		}
156		return sharedcomponents.Status{}
157	}
158	
159	// agentsStatus is the footer state of the agents level.
160	func (m Model) agentsStatus() sharedcomponents.Status {
161		switch {
162		case m.agentsErr:
163			return sharedcomponents.Status{
164				Text:  "Failed to read this session — check logs",
165				Level: sharedcomponents.LevelError,
166			}
167		case m.agentsLoading:
168			return sharedcomponents.Status{Text: "Reading session...", Spinner: true}
169		case m.usage.Diagnostics.Degraded():
170			return sharedcomponents.Status{
171				Text:  "Totals are approximate — some transcript data could not be read",
172				Level: sharedcomponents.LevelWarning,
173			}
174		}
175		return sharedcomponents.Status{}
176	}
