// formatNetBytes formats bytes into a compact human-readable string (e.g. "1.2kB", "3.4MB")
func formatNetBytes(b int64) string {
	switch {
	case b >= 1e9:
		return fmt.Sprintf("%.1fGB", float64(b)/1e9)
	case b >= 1e6:
		return fmt.Sprintf("%.1fMB", float64(b)/1e6)
	case b >= 1e3:
		return fmt.Sprintf("%.1fkB", float64(b)/1e3)
	default:
		return fmt.Sprintf("%dB", b)
	}
}

// stateIcon returns a compact Nerd Font icon representing the container state
func stateIcon(state string) string {
	switch state {
	case "running":
		return theme.IconCaretRight
	case "paused":
		return theme.IconSmallPause
	case "exited":
		return theme.IconSmallSquare
	case "created", "restarting":
		return theme.IconCaretUp
	case "dead":
		return theme.IconBan
	default:
		return theme.IconGitUntracked
	}
}","merged_ranks":[1,3,4]},{"rank":2,"score":38.4237,"file_path":"internal/ui/containers/model.go","start_line":155,"end_line":269,"focus_line":168,"snippet_start_line":155,"snippet_end_line":269,"symbol_start_line":155,"symbol_end_line":269,"language":"Go","kind":"function","symbol_id":"local/devdesk:Go:internal/ui/containers/model.go:function:containerColumns","symbol_name":"containerColumns","qualified_name":"containerColumns","signature":"func containerColumns(status func(docker.Container) imageupdate.Status) []datatable.Column[docker.Container]","signals":["body","signature","symbol-usage","complete-symbol"],"snippet":"func containerColumns(status func(docker.Container) imageupdate.Status) []datatable.Column[docker.Container] {
